from pathlib import Path

path = Path('/home/ubuntu/nexbet-black-gold/client/src/App.tsx')
source = path.read_text()
start = source.index('function AccountAuth(')
end = source.index('\nfunction Router()', start)
replacement = r'''function AccountAuth({ mode }: { mode: "login" | "register" }) {
  const isLogin = mode === "login";
  const [step, setStep] = useState<1 | 2>(1);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [remember, setRemember] = useState(true);
  const [terms, setTerms] = useState(false);
  const [notice, setNotice] = useState("");
  const [form, setForm] = useState({ identifier: "", password: "", confirm: "", firstName: "", lastName: "", phone: "", referral: "" });
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const passwordStrong = form.password.length >= 8 && /[A-Za-z]/.test(form.password) && /[0-9]/.test(form.password);
  const Field = ({ label, field, type = "text", placeholder = "" }: { label: string; field: keyof typeof form; type?: string; placeholder?: string }) => <label className="auth-field"><span>{label}</span><input value={form[field]} onChange={(e) => update(field, e.target.value)} type={type} placeholder={placeholder} /></label>;
  const PasswordField = ({ confirm = false }: { confirm?: boolean }) => { const visible = confirm ? showConfirm : showPassword; const field = confirm ? "confirm" : "password"; return <label className="auth-field"><span>{confirm ? "Confirm password" : "Password"}</span><div className="auth-input-wrap"><input value={form[field]} onChange={(e) => update(field, e.target.value)} type={visible ? "text" : "password"} placeholder={confirm ? "Repeat your password" : "At least 8 characters"} /><button type="button" onClick={() => confirm ? setShowConfirm(!showConfirm) : setShowPassword(!showPassword)}>{visible ? "Hide" : "Show"}</button></div>{!confirm && form.password && <small className={passwordStrong ? "valid-text" : "error-text"}>{passwordStrong ? "Strong password" : "Use 8+ characters with a letter and number"}</small>}</label>; };
  const submit = (event: React.FormEvent) => { event.preventDefault(); setNotice(""); if (isLogin) { if (!form.identifier || !form.password) return setNotice("Enter your phone or email and password to continue."); window.location.href = "/"; return; } if (step === 1) { if (!form.identifier || !passwordStrong || form.password !== form.confirm) return setNotice("Check your email, password, and confirmation before continuing."); setStep(2); return; } if (!form.firstName || !form.lastName || !form.phone || !terms) return setNotice("Complete your profile and accept the terms to create your account."); window.location.href = "/login"; };
  return <><Header onMenu={() => document.body.classList.toggle("menu-open")} /><main className="auth-page"><div className="auth-intro"><span className="eyebrow">{isLogin ? "Welcome back" : "Account setup"}</span><h1>{isLogin ? <>Bet smarter.<br/><em>Stay ahead.</em></> : <>Your next win<br/><em>starts here.</em></>}</h1><p>{isLogin ? "Access your balance, betslip, live markets, and HotBet rewards." : "Create your HotBet account in under two minutes and make every market count."}</p><div className="auth-benefits"><span><ShieldCheck size={16}/> Secure account</span><span><Zap size={16}/> Fast markets</span><span><Gift size={16}/> Exclusive offers</span></div></div><section className="panel auth-card auth-card-premium"><div className="auth-card-head"><div className="auth-crown"><Crown size={20}/></div><div><span className="eyebrow">HotBet Ghana</span><h2>{isLogin ? "Log in" : step === 1 ? "Create your account" : "Complete your profile"}</h2></div></div>{!isLogin && <div className="auth-steps"><span className={step === 1 ? "active" : "done"}>1 <small>Account</small></span><i className={step === 2 ? "active" : ""}/><span className={step === 2 ? "active" : ""}>2 <small>Profile</small></span></div>}<form onSubmit={submit}>{isLogin && <><Field label="Phone or email" field="identifier" placeholder="name@example.com" /><PasswordField /><div className="auth-row"><label className="check-row"><input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} /> Remember me</label><Link href="/help">Forgot password?</Link></div></>}{!isLogin && step === 1 && <><Field label="Email address" field="identifier" type="email" placeholder="name@example.com" /><PasswordField /><PasswordField confirm /></>}{!isLogin && step === 2 && <><div className="auth-two-col"><Field label="First name" field="firstName" placeholder="Kwame" /><Field label="Last name" field="lastName" placeholder="Mensah" /></div><Field label="Phone number" field="phone" type="tel" placeholder="+233 24 000 0000" /><Field label="Referral code" field="referral" placeholder="Optional" /><label className="check-row terms-row"><input type="checkbox" checked={terms} onChange={(e) => setTerms(e.target.checked)} /> I agree to the <Link href="/">terms and responsible gaming policy</Link></label></>}<button className="gold-button full auth-submit" type="submit">{isLogin ? "Log in to HotBet" : step === 1 ? "Continue" : "Create account"}<ChevronRight size={16}/></button>{notice && <div className="auth-notice" role="alert">{notice}</div>}</form>{!isLogin && step === 2 && <button className="auth-back" type="button" onClick={() => setStep(1)}>Back to account details</button>}<p className="auth-switch">{isLogin ? "New to HotBet?" : "Already have an account?"} <Link href={isLogin ? "/register" : "/login"}>{isLogin ? "Create an account" : "Log in"}</Link></p><div className="auth-safe"><ShieldCheck size={15}/> Your information is protected with secure account controls.</div></section></main><Footer /></>;
}
'''
path.write_text(source[:start] + replacement + source[end:])
